import React from 'react';
import { useToggle } from './hooks/useToggle';
import './styles.css';

export default function App() {
  // TODO: Call useToggle(false) to get [isExpanded, toggleExpanded]
  const [isExpanded, toggleExpanded] = useToggle(false);

  return (
    <div className="accordion-card">
      <div className="header-row">
        <h3>Server Metrics</h3>
        <button 
          id="toggle-panel-btn" 
          className="btn-primary" 
          onClick={toggleExpanded}
        >
          {isExpanded ? 'Hide Details ▲' : 'Show Details ▼'}
        </button>
      </div>

      {isExpanded && (
        <div id="panel-details" className="details-box">
          <p>CPU Utilization: <strong>14.2%</strong></p>
          <p>Memory Usage: <strong>2.1 GB / 8 GB</strong></p>
          <p>Network Status: <span style={{ color: '#16a34a' }}>Healthy 🟢</span></p>
        </div>
      )}
    </div>
  );
}

